'use strict';
// REGREV quality optimizer. Research only. DEV 75% selects; HOLD 25% is untouched until final print.
const fs=require('fs'),R=JSON.parse(fs.readFileSync('data/xauusd-m5-dukascopy.json','utf8'));
const M=R.map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t),N=M.length,C=Math.floor(N*.75);
function ema(p){let E=[],e=M[0].c,k=2/(p+1);for(let i=0;i<N;i++){e=M[i].c*k+e*(1-k);E[i]=e}return E}function atr(p=14){let A=Array(N).fill(NaN);for(let i=p;i<N;i++){let s=0;for(let j=i-p+1;j<=i;j++)s+=Math.max(M[j].h-M[j].l,Math.abs(M[j].h-M[j-1].c),Math.abs(M[j].l-M[j-1].c));A[i]=s/p}return A}const A=atr(),E=ema(20);function aa(i,n=50){let s=0,c=0;for(let j=i-n;j<i;j++)if(Number.isFinite(A[j])){s+=A[j];c++}return c?s/c:NaN}const H=i=>new Date(M[i].t).getUTCHours();
function sig(i,q){let av=aa(i);if(!(A[i]/av>=q.ar))return;let b=M[i],rg=b.h-b.l;if(!(rg>0))return;let body=Math.abs(b.c-b.o)/rg;if(body<q.body)return;let cpBuy=(b.c-b.l)/rg,cpSell=(b.h-b.c)/rg;if(q.side!=='SELL'&&(E[i]-b.c)/A[i]>=q.dist&&b.c>b.o&&cpBuy>=q.cp&&!q.block.includes(H(i)))return'BUY';if(q.side!=='BUY'&&(b.c-E[i])/A[i]>=q.dist&&b.c<b.o&&cpSell>=q.cp&&!q.block.includes(H(i)))return'SELL'}
function run(q,lo,hi){let T=[],o=null;for(let i=Math.max(100,lo);i<Math.min(N-1,hi);i++){if(o){let b=M[i],px=null;if(o.s==='BUY'){if(b.l<=o.sl)px=o.sl;else if(b.h>=o.tp)px=o.tp}else{if(b.h>=o.sl)px=o.sl;else if(b.l<=o.tp)px=o.tp}if(px==null&&i-o.ei+1>=q.hold)px=b.c;if(px!=null){T.push({...o,xi:i,xt:b.t,r:o.s==='BUY'?(px-o.en)/(o.en-o.sl):(o.en-px)/(o.sl-o.en)});o=null}continue}let s=sig(i,q);if(!s)continue;let en=M[i+1].o,r=q.sl*A[i];o={s,en,sl:s==='BUY'?en-r:en+r,tp:s==='BUY'?en+q.rr*r:en-q.rr*r,ei:i+1,et:M[i+1].t}}return T}function st(T){let w=0,g=0,l=0,e=0,p=0,d=0,ls=0,ml=0;for(let x of T){e+=x.r;if(x.r>0){w++;g+=x.r;ls=0}else{l+=-x.r;ls++;ml=Math.max(ml,ls)}p=Math.max(p,e);d=Math.max(d,p-e)}return{n:T.length,wr:T.length?100*w/T.length:0,pf:l?g/l:g?Infinity:0,net:e,dd:d,ls:ml}}
let blocks=[[],[0,1,2,3,4,5],[6,7,8],[16,17,18,19],[20,21,22,23]];let X=[];for(let side of ['BOTH','BUY','SELL'])for(let ar of [1.25,1.4,1.5,1.65,1.8])for(let dist of [1.75,2,2.25])for(let cp of [.65,.75,.8])for(let body of [0,.35,.5])for(let rr of [1.25,1.5,1.75])for(let sl of [.8,1,1.2])for(let hold of [8,10,12])for(let block of blocks){let q={side,ar,dist,cp,body,rr,sl,hold,block},d=st(run(q,0,C));if(d.n<35)continue;let score=d.net+Math.min(d.pf,3)*8-d.dd*.8+(d.wr-45)*.15;X.push({q,d,score})}X.sort((a,b)=>b.score-a.score);
console.log(`REGREV QUALITY OPTIMIZER | M5=${N} DEV=${C} HOLD=${N-C}`);console.log('\n🏆 TOP 30 DEV → UNTOUCHED HOLD');X.slice(0,30).forEach((x,k)=>{let h=st(run(x.q,C,N));console.log(`${k+1} ${JSON.stringify(x.q)} | DEV T${x.d.n} WR${x.d.wr.toFixed(1)} PF${x.d.pf.toFixed(2)} N${x.d.net>=0?'+':''}${x.d.net.toFixed(2)} DD${x.d.dd.toFixed(2)} LS${x.d.ls} | HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.net>=0?'+':''}${h.net.toFixed(2)} DD${h.dd.toFixed(2)} LS${h.ls}`)});
console.log('\nSIDE BASELINES');for(let side of ['BOTH','BUY','SELL']){let q={side,ar:1.5,dist:2,cp:.65,body:0,rr:1.5,sl:1,hold:10,block:[]};let d=st(run(q,0,C)),h=st(run(q,C,N));console.log(`${side} | DEV T${d.n} WR${d.wr.toFixed(1)} PF${d.pf.toFixed(2)} N${d.net.toFixed(2)} DD${d.dd.toFixed(2)} | HOLD T${h.n} WR${h.wr.toFixed(1)} PF${h.pf.toFixed(2)} N${h.net.toFixed(2)} DD${h.dd.toFixed(2)}`)}
console.log('\nNEXT: choose a parameter NEIGHBORHOOD, not one lucky row; then locked 6-block/month/cost validation and exact current-8 collision test.');